package com.example.code.data

import com.example.code.model.Lottery

interface LotteryUpdateRepository {
    /**
     * Updates the same lottery document, rechecking ownership, current state,
     * and the original configuration inside the persistence transaction.
     * Throws on stale settings, closed registration, or invalid changes.
     */
    suspend fun updateLottery(original: Lottery, ownerId: String, changes: Lottery)
}

/**
 * Only editable listing fields. Dynamic waitlist/draw fields are never written.
 * Explicitly clearing capacity and campsite arrays prevents old values lingering.
 */
fun lotteryUpdateToMap(lottery: Lottery): Map<String, Any?> = mapOf(
    "campsiteId" to lottery.campsiteId,
    "campsiteName" to lottery.campsiteName,
    "registrationStart" to lottery.registrationStart,
    "registrationEnd" to lottery.registrationEnd,
    "bookingStart" to lottery.bookingStart,
    "bookingEnd" to lottery.bookingEnd,
    "winnerCount" to lottery.winnerCount,
    "waitlistCapacity" to lottery.waitlistCapacity,
    "campsites" to lottery.campsites.map { mapOf("id" to it.id, "name" to it.name) },
)
